      || (typeof trackUrl === 'string' && trackUrl ? pathsEqual(trackUrl, path) : false);
    if (isCurrent && Array.isArray(lines)) {
      set({ lyrics: sortLyricLines(lines), lyricStatus: 'found' });
    }
  });
